<?php require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/header.php'; $id=(int)($_GET['id']??0);$st=$pdo->prepare("SELECT b.*,COALESCE((SELECT SUM(amount) FROM payments p WHERE p.bill_id=b.id),0) paid FROM bills b WHERE b.id=?");$st->execute([$id]);$b=$st->fetch();if(!$b){exit('Bill haipo');}$balance=max(0,$b['total']-$b['paid']);$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$amt=(float)$_POST['amount'];if($amt<=0||$amt>$balance){$error='Kiasi si sahihi.';}else{$pdo->beginTransaction();$receipt='R'.date('YmdHis').rand(10,99);$pdo->prepare('INSERT INTO payments(bill_id,receipt_no,amount,method,reference_no,cashier_id) VALUES(?,?,?,?,?,?)')->execute([$id,$receipt,$amt,$_POST['method'],trim($_POST['reference_no']??'')?:null,$_SESSION['user']['id']]);$new=$b['paid']+$amt;$status=$new >= $b['total'] ? 'PAID':'PARTIAL';$pdo->prepare('UPDATE bills SET status=? WHERE id=?')->execute([$status,$id]);$pid=$pdo->lastInsertId();$pdo->commit();header('Location: ../prints/receipt.php?id='.$pid);exit;}}?><h2>Pokea Malipo</h2><?php if($error):?><div class="alert danger"><?=e($error)?></div><?php endif;?><div class="card"><p><b>Bill:</b> <?=e($b['bill_no'])?></p><p><b>Jumla:</b> TSh <?=number_format($b['total'],2)?></p><p><b>Imelipwa:</b> TSh <?=number_format($b['paid'],2)?></p><p><b>Balance:</b> TSh <?=number_format($balance,2)?></p><form method="post"><label>Kiasi cha Malipo</label><input type="number" step="0.01" min="0.01" max="<?=$balance?>" name="amount" value="<?=$balance?>" required><label>Njia ya Malipo</label><select name="method"><option>CASH</option><option>MOBILE</option><option>CARD</option><option>BANK</option></select><label>Reference No. (hiari)</label><input name="reference_no"><button class="green">Pokea Malipo na Print Receipt</button></form></div><?php require_once __DIR__.'/../config/footer.php'; ?>
